const payload = msg.payload;
const required = ["plant_id", "component_id", "sensor_id", "timestamp", "value", "unit", "quality"];

for (const field of required) {
    if (payload[field] === undefined || payload[field] === null || payload[field] === "") {
        msg.payload = `Invalid telemetry payload. Missing field: ${field}`;
        return [null, msg];
    }
}

const value = Number(payload.value);
if (Number.isNaN(value)) {
    msg.payload = "Invalid telemetry payload. value must be numeric.";
    return [null, msg];
}

const measuredAt = new Date(payload.timestamp);
if (Number.isNaN(measuredAt.getTime())) {
    msg.payload = "Invalid telemetry payload. timestamp must be ISO-8601.";
    return [null, msg];
}

// Reference Platform 1.0 usa directamente variables reales Mesa del Sol.
// El sensor_id MQTT debe coincidir con variable_catalog.code.
const allowedVariables = new Set([
    "Battery_Active_Power",
    "PVPCS_Active_Power",
    "GE_Active_Power",
    "FC_Active_Power",
    "Island_mode_MCCB_Active_Power",
    "MG-LV-MSB_AC_Voltage",
    "Receiving_Point_AC_Voltage",
    "MG-LV-MSB_Frequency",
    "Inlet_Temperature_of_Chilled_Water",
    "Outlet_Temperature"
]);

const componentMap = {
    "BAT1": "BAT1",
    "PV1": "PV1",
    "GE1": "GE1",
    "FC1": "FC1",
    "MCCB1": "MCCB1",
    "BUS1": "BUS1",
    "PCC1": "PCC1",
    "COOL1": "COOL1"
};

const componentCode = componentMap[String(payload.component_id || "")];
const variableCode = String(payload.sensor_id || "");

if (!componentCode) {
    msg.payload = `Telemetry component is not mapped to the SQL catalog: ${payload.component_id}`;
    return [null, msg];
}

if (!allowedVariables.has(variableCode)) {
    msg.payload = `Telemetry variable is not part of the Mesa del Sol Reference 1.0 catalog: ${variableCode}`;
    return [null, msg];
}

msg.query = `
insert into measurement (component_id, variable_id, ts, value, quality)
select c.id, vc.id, $3::timestamptz, $4::double precision, $5::text
from component c
join variable_catalog vc on vc.code = $2::text
where c.code = $1::text
returning id, component_id, variable_id, ts, value, quality;
`;

msg.params = [
    componentCode,
    variableCode,
    measuredAt.toISOString(),
    value,
    payload.quality
];

msg.payload = {
    mqtt: payload,
    sql_component_code: componentCode,
    sql_variable_code: variableCode
};

return [msg, null];

const payload = msg.payload;

function escapeSql(value) {
    return String(value).replace(/'/g, "''");
}

if (!payload || typeof payload !== "object") {
    msg.payload = "Invalid command payload. Expected JSON object.";
    return null;
}

const componentMap = {
    "battery": "BAT1",
    "pv": "PV1",
    "grid": "PCC1",
    "simulator": "MCCB1"
};

const mqttComponentId = String(payload.component_id || "");
const sqlComponentCode = componentMap[mqttComponentId] || mqttComponentId;
const componentCode = sqlComponentCode.replace(/'/g, "''");
const command = payload.command;
const ts = payload.ts || new Date().toISOString();

if (!mqttComponentId || !command) {
    msg.payload = "Invalid command payload. component_id and command are required.";
    return null;
}

let valueSql = "NULL";
if (payload.value === "on") {
    valueSql = "1";
} else if (payload.value === "off") {
    valueSql = "0";
} else if (payload.value !== undefined && payload.value !== null && payload.value !== "") {
    const numericValue = Number(payload.value);
    valueSql = Number.isNaN(numericValue) ? "NULL" : String(numericValue);
}

const sql = `INSERT INTO "command" (component_id, ts, command, value, status)
SELECT
  c.id,
  '${escapeSql(ts)}'::timestamp,
  '${escapeSql(command)}',
  ${valueSql},
  'received'
FROM component c
WHERE c.code = '${componentCode}';`;

msg.query = sql;
msg.topic = sql;
return msg;

const value = msg.payload === "on" ? "on" : "off";
const commandId = value === "on" ? "cmd-ui-on" : "cmd-ui-off";

const payload = {
    command_id: commandId,
    plant_id: "mds",
    component_id: "battery",
    command: "set_status",
    value: value,
    requested_by: "nodered-console",
    ts: new Date().toISOString()
};

msg.topic = `seda/plants/mds/components/battery/commands/${commandId}`;
msg.payload = JSON.stringify(payload);
return msg;

const payload = msg.payload;

function escapeSql(value) {
    return String(value).replace(/'/g, "''");
}

if (!payload || typeof payload !== "object") {
    return [null, null];
}

const value = Number(payload.value);
if (Number.isNaN(value)) {
    return [null, null];
}

const componentCode = String(payload.component_id || "");
const variableCode = String(payload.sensor_id || "");
const rules = {
    "Outlet_Temperature": {
        alarmCode: "HIGH_OUTLET_TEMPERATURE",
        triggered: value > 30,
        message: `Outlet_Temperature is high: ${value} ${payload.unit || ""}`
    },
    "MG-LV-MSB_Frequency_LOW": {
        alarmCode: "LOW_FREQUENCY",
        triggered: variableCode === "MG-LV-MSB_Frequency" && value < 59.97,
        message: `MG-LV-MSB_Frequency is low: ${value} ${payload.unit || ""}`
    },
    "MG-LV-MSB_Frequency_HIGH": {
        alarmCode: "HIGH_FREQUENCY",
        triggered: variableCode === "MG-LV-MSB_Frequency" && value > 60.03,
        message: `MG-LV-MSB_Frequency is high: ${value} ${payload.unit || ""}`
    },
    "Receiving_Point_AC_Voltage_LOW": {
        alarmCode: "LOW_VOLTAGE",
        triggered: variableCode === "Receiving_Point_AC_Voltage" && value < 478,
        message: `Receiving_Point_AC_Voltage is low: ${value} ${payload.unit || ""}`
    },
    "Receiving_Point_AC_Voltage_HIGH": {
        alarmCode: "HIGH_VOLTAGE",
        triggered: variableCode === "Receiving_Point_AC_Voltage" && value > 488,
        message: `Receiving_Point_AC_Voltage is high: ${value} ${payload.unit || ""}`
    }
};

const candidates = [];
if (rules[variableCode]) {
    candidates.push(rules[variableCode]);
}
if (variableCode === "MG-LV-MSB_Frequency") {
    candidates.push(rules["MG-LV-MSB_Frequency_LOW"], rules["MG-LV-MSB_Frequency_HIGH"]);
}
if (variableCode === "Receiving_Point_AC_Voltage") {
    candidates.push(rules["Receiving_Point_AC_Voltage_LOW"], rules["Receiving_Point_AC_Voltage_HIGH"]);
}

const rule = candidates.find(candidate => candidate && candidate.triggered);
if (!rule) {
    return [null, null];
}

const ts = payload.timestamp || new Date().toISOString();
const alarmSql = `INSERT INTO alarm (component_id, ts, severity, code, message)
SELECT
  c.id,
  '${escapeSql(ts)}'::timestamp,
  'warning',
  '${escapeSql(rule.alarmCode)}',
  '${escapeSql(rule.message)}'
FROM component c
WHERE c.code = '${escapeSql(componentCode)}'
  AND NOT EXISTS (
    SELECT 1
    FROM alarm a
    WHERE a.component_id = c.id
      AND a.code = '${escapeSql(rule.alarmCode)}'
      AND a.ts >= '${escapeSql(ts)}'::timestamp - interval '60 seconds'
  )
RETURNING id, component_id, ts, severity, code, message;`;

const sqlMsg = {
    ...msg,
    query: alarmSql,
    topic: alarmSql,
    payload: {
        alarm_code: rule.alarmCode,
        component_code: componentCode,
        variable_code: variableCode,
        value: value
    }
};

const mqttPayload = {
    plant_id: payload.plant_id || "mds",
    alarm_code: rule.alarmCode,
    severity: "warning",
    component_id: componentCode,
    variable_id: variableCode,
    value: value,
    ts: ts
};

const mqttMsg = {
    topic: `seda/plants/mds/alarms/${rule.alarmCode}`,
    payload: JSON.stringify(mqttPayload)
};

return [sqlMsg, mqttMsg];

msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json" };
msg.payload = JSON.stringify({
    platform: "SEDA-Lab",
    version: "reference-1.0",
    status: "ok"
});
return msg;

const rows = Array.isArray(msg.payload)
    ? msg.payload
    : (msg.payload && Array.isArray(msg.payload.rows) ? msg.payload.rows : []);
msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json" };
msg.payload = JSON.stringify(rows);
return msg;

